def execute(arguments):
    """
    列出目录内容

    参数:
        arguments (dict): 包含以下字段
            - path (str): 目录路径，必填
            - pattern (str): 文件名匹配模式，支持通配符，默认 "*"
            - show_hidden (bool): 是否显示隐藏文件，默认 False

    返回:
        dict: 包含目录信息的字典
            - success (bool): 是否成功
            - path (str): 目录路径
            - items (list): 文件/目录列表，每项包含 name, type, size, modified
            - count (int): 项目数量
            - error (str): 错误信息（失败时）
    """
    import os
    import fnmatch

    path = arguments.get("path", "")
    pattern = arguments.get("pattern", "*")
    show_hidden = arguments.get("show_hidden", False)

    if not path:
        return {"success": False, "error": "请提供目录路径"}

    if not os.path.exists(path):
        return {"success": False, "error": f"目录不存在: {path}"}

    if not os.path.isdir(path):
        return {"success": False, "error": f"路径不是目录: {path}"}

    try:
        items = []
        for item in os.listdir(path):
            if not show_hidden and item.startswith("."):
                continue
            if not fnmatch.fnmatch(item, pattern):
                continue

            item_path = os.path.join(path, item)
            is_dir = os.path.isdir(item_path)
            size = 0 if is_dir else os.path.getsize(item_path)
            mtime = os.path.getmtime(item_path)

            items.append({
                "name": item,
                "type": "directory" if is_dir else "file",
                "size": size,
                "modified": mtime
            })

        items.sort(key=lambda x: (x["type"] == "file", x["name"].lower()))

        return {
            "success": True,
            "path": path,
            "items": items,
            "count": len(items)
        }
    except Exception as e:
        return {"success": False, "error": str(e)}
